INSERT INTO changelog (title, body, created_at) VALUES
('Джері бачить усе в папках клієнтів на Диску',
'Раніше система мала доступ тільки до файлів, які створила сама (так влаштований дозвіл Google «drive.file»), тому креативи, закинуті руками, Джері не бачив. Тепер є дозвіл на перегляд Диску: інструмент drive_list показує все в папці клієнта (з підпапками, датами, розмірами), а view_images відкриває картинки звідти. Щоб увімкнути — один раз: Налаштування → Конектори → Google → «Перепідключити» і погодитись на перегляд файлів. Писати система й далі буде тільки у свої папки. Питай: «глянь, що в креативах ProVector, і оціни нові банери».',
'2026-11-01 20:00:00');
